I have this function that looks unnecessarily complex. Simplify it:

function processOrder(order) {
  if (order.items && order.items.length > 0) {
    if (order.payment && order.payment.status === 'completed') {
      if (!order.shipping || order.shipping.status !== 'shipped') {
        return { success: true, total: order.items.reduce((s, i) => s + i.price * i.qty, 0) };
      } else {
        return { success: false, error: 'already shipped' };
      }
    } else {
      return { success: false, error: 'payment not completed' };
    }
  } else {
    return { success: false, error: 'no items' };
  }
}

This function works but is hard to read. Simplify it WITHOUT changing what it does:

function getDiscount(customer) {
  let discount = 0;
  if (customer.tier === 'gold') {
    discount = discount + 0.2;
    if (customer.years > 5) {
      discount = discount + 0.05;
    }
    if (customer.referrals > 10) {
      discount = discount + 0.03;
    }
  } else if (customer.tier === 'silver') {
    discount = discount + 0.1;
    if (customer.years > 3) {
      discount = discount + 0.02;
    }
  }
  return Math.min(discount, 0.3);
}
